private void renderLeg(ItemStack legItem, LivingEntity entity, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn, boolean glintIn, HumanoidModel modelIn, float red, float green, float blue, ResourceLocation armorResource, boolean notAVanillaModel) {
        VertexConsumer ivertexbuilder = ItemRenderer.getFoilBuffer(bufferIn, RenderType.entityCutoutNoCull(armorResource), false, glintIn);
        renderer.getModel().copyPropertiesTo(modelIn);
        modelIn.body.xRot = 0F;
        modelIn.body.yRot = 0;
        modelIn.body.zRot = 0;
        modelIn.body.x = 0;
        modelIn.body.y = 0F;
        modelIn.body.z = 0F;
        modelIn.rightLeg.x = 0F;
        modelIn.rightLeg.xRot = 0F;
        modelIn.rightLeg.yRot = 0F;
        modelIn.rightLeg.zRot = 0F;
        modelIn.leftLeg.x = 0F;
        modelIn.leftLeg.xRot = 0F;
        modelIn.leftLeg.yRot = 0F;
        modelIn.leftLeg.zRot = 0F;
        modelIn.leftLeg.y = 0F;
        modelIn.rightLeg.y = 0F;
        modelIn.leftLeg.z = 0F;
        modelIn.rightLeg.z = 0F;
        renderer.getModel().rightLegPartArmors().forEach(part -> {
            matrixStackIn.pushPose();
            renderer.getModel().translateToLeg(part, matrixStackIn);
            modelIn.rightLeg.render(matrixStackIn, ivertexbuilder, packedLightIn, OverlayTexture.NO_OVERLAY, red, green, blue, 1.0F);
            matrixStackIn.popPose();
        });
        renderer.getModel().leftLegPartArmors().forEach(part -> {
            matrixStackIn.pushPose();
            renderer.getModel().translateToLeg(part, matrixStackIn);
            modelIn.leftLeg.render(matrixStackIn, ivertexbuilder, packedLightIn, OverlayTexture.NO_OVERLAY, red, green, blue, 1.0F);
            matrixStackIn.popPose();
        });
        renderer.getModel().bodyPartArmors().forEach(part -> {
            matrixStackIn.pushPose();
            renderer.getModel().translateToChest(part, matrixStackIn);
            modelIn.body.render(matrixStackIn, ivertexbuilder, packedLightIn, OverlayTexture.NO_OVERLAY, red, green, blue, 1.0F);
            matrixStackIn.popPose();
        });
        if (MobsConfig.HierarchicalArmorTrim.get()) {
            ArmorTrim.getTrim(entity.level().registryAccess(), legItem).ifPresent(armorTrim -> {
                if (legItem.getItem() instanceof ArmorItem armorItem) {
                    TextureAtlasSprite sprite = this.armorTrimAtlas.getSprite(armorTrim.innerTexture(armorItem.getMaterial()));
                    renderer.getModel().rightLegPartArmors().forEach(part -> {
                        matrixStackIn.pushPose();
                        renderer.getModel().translateToLeg(part, matrixStackIn);
                        VertexConsumer consumer = sprite.wrap(ItemRenderer.getFoilBufferDirect(bufferIn, Sheets.armorTrimsSheet(), false, glintIn));
                        modelIn.rightLeg.render(matrixStackIn, consumer, packedLightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
                        matrixStackIn.popPose();
                    });
                    renderer.getModel().leftLegPartArmors().forEach(part -> {
                        matrixStackIn.pushPose();
                        renderer.getModel().translateToLeg(part, matrixStackIn);
                        VertexConsumer consumer = sprite.wrap(ItemRenderer.getFoilBufferDirect(bufferIn, Sheets.armorTrimsSheet(), false, glintIn));
                        modelIn.leftLeg.render(matrixStackIn, consumer, packedLightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
                        matrixStackIn.popPose();
                    });
                    renderer.getModel().bodyPartArmors().forEach(part -> {
                        matrixStackIn.pushPose();
                        renderer.getModel().translateToChest(part, matrixStackIn);
                        VertexConsumer consumer = sprite.wrap(ItemRenderer.getFoilBufferDirect(bufferIn, Sheets.armorTrimsSheet(), false, glintIn));
                        modelIn.body.render(matrixStackIn, consumer, packedLightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
                        matrixStackIn.popPose();
                    });
                }
            });
        }
    }

@Override
    public <STATE extends HumanoidRenderState> void render(HumanoidModel<STATE> baseModel, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords,
          STATE state, boolean isBaby, ItemStack stack) {
        Map<ModelPos, PartData> armorQuads = cache.getUnchecked(key(state));
        boolean renderFoil = stack.hasFoil();

        if (!armorQuads.isEmpty()) {
            int tintColor = getColor(stack);
            for (Map.Entry<ModelPos, PartData> entry : armorQuads.entrySet()) {
                ModelPos modelPos = entry.getKey();
                poseStack.pushPose();
                modelPos.translate(baseModel, poseStack, state);
                if (isBaby) {
                    modelPos.scaleBaby(poseStack, state);
                }
                modelPos.translateModel(poseStack);
                entry.getValue().render(poseStack, nodeCollector, lightCoords, state.outlineColor, tintColor, renderFoil);
                poseStack.popPose();
            }
        }


        if (type == EquipmentSlot.CHEST) {
            UUID entityUUID = state.getRenderData(UUID_CONTEXT);
            if (entityUUID != null) {
                long gameTime = Minecraft.getInstance().level == null ? 0L : Minecraft.getInstance().level.getGameTime();
                BoltRenderer boltRenderer = boltRenderMap.computeIfAbsent(entityUUID, _ -> new BoltRenderer());
                if (IModuleHelper.INSTANCE.isEnabled(state.chestEquipment, MekanismModules.GRAVITATIONAL_MODULATING_UNIT)) {
                    boltRenderer.update(0, LEFT_GRAV_BOLT, gameTime, state.partialTick);
                    boltRenderer.update(1, RIGHT_GRAV_BOLT, gameTime, state.partialTick);
                }
                List<BoltRenderState> boltRenderStates = boltRenderer.collectBoltStates(gameTime, state.partialTick);
                if (!boltRenderStates.isEmpty()) {
                    //Adjust the poseStack so that we render the lightning in the correct spot if the player is crouching
                    poseStack.pushPose();
                    ModelPos.BODY.translate(baseModel, poseStack, state);
                    PoseStack.Pose pose = poseStack.last().copy();
                    for (BoltRenderState boltState : boltRenderStates) {
                        nodeCollector.submitSpecial(RenderPhaseKeys.TRANSLUCENT_CUSTOM_GEOMETRY, new BoltFeatureRenderer.Submit(pose, boltState));
                    }
                    poseStack.popPose();
                }
            }
        }
    }

public QuickHash key(HumanoidRenderState state) {
        Object2BooleanMap<ModuleModelSpec> modules = new Object2BooleanOpenHashMap<>();
        Set<EquipmentSlot> wornParts = EnumSet.noneOf(EquipmentSlot.class);
        for (EquipmentSlot slotType : EquipmentSlotGroup.ARMOR) {
            ItemStack stack = getItemBySlot(state, slotType);
            if (stack.getItem() instanceof ItemMekaSuitArmor) {
                IModuleContainer container = IModuleHelper.INSTANCE.getModuleContainer(stack);
                if (container != null) {
                    wornParts.add(slotType);
                    for (Entry<Holder<ModuleData<?>>, ModuleModelSpec> entry : moduleModelSpec.row(slotType).entrySet()) {
                        if (container.hasEnabled(entry.getKey())) {
                            ModuleModelSpec spec = entry.getValue();
                            modules.put(spec, spec.isActive(state));
                        }
                    }
                }
            }
        }
        return new QuickHash(modules.isEmpty() ? Object2BooleanMaps.emptyMap() : modules, wornParts.isEmpty() ? Collections.emptySet() : wornParts,
              getItemBySlot(state, state.mainArm == HumanoidArm.LEFT ? EquipmentSlot.MAINHAND : EquipmentSlot.OFFHAND).getItem() instanceof ItemMekaTool,
              getItemBySlot(state, state.mainArm == HumanoidArm.RIGHT ? EquipmentSlot.MAINHAND : EquipmentSlot.OFFHAND).getItem() instanceof ItemMekaTool);
    }

private static void drawWoundEnergy(VertexConsumer vertices, Matrix4f matrix, float age,
                                        long seed, int index, int count, float height,
                                        float radius, float bodyYaw, int primaryColor, int coreColor) {
        float angle = woundAngle(seed, index, count, bodyYaw);
        Vec3d outward = new Vec3d(MathHelper.sin(angle), 0.0, MathHelper.cos(angle));
        Vec3d tangent = new Vec3d(outward.z, 0.0, -outward.x);
        float tilt = woundTilt(seed, index);
        Vec3d longAxis = tangent.multiply(MathHelper.cos(tilt)).add(UP.multiply(MathHelper.sin(tilt)));
        Vec3d shortAxis = UP.multiply(MathHelper.cos(tilt)).subtract(tangent.multiply(MathHelper.sin(tilt)));
        float halfLength = woundHalfLength(seed, index, height);
        float halfWidth = woundHalfWidth(seed, index, halfLength);
        Vec3d center = woundCenter(seed, index, height, radius, outward).add(outward.multiply(0.018F));
        float pulse = 0.86F + MathHelper.sin(age * 0.16F + index * 1.73F) * 0.12F;
        int purple = scaleColor(primaryColor, 1.9F);
        int paleCore = mixColor(coreColor, 0xFFFFFF, 0.34F);
        for (int segment = 0; segment < 3; segment++) {
            Vec3d start = woundCorePoint(seed, index, segment, center, longAxis, shortAxis,
                    halfLength, halfWidth);
            Vec3d end = woundCorePoint(seed, index, segment + 1, center, longAxis, shortAxis,
                    halfLength, halfWidth);
            float taper = 1.0F - Math.abs(segment - 1) * 0.14F;
            woundGlowRibbon(vertices, matrix, start, end, shortAxis,
                    halfWidth * 0.21F * taper, outward, purple, Math.round(184.0F * pulse));
            woundGlowRibbon(vertices, matrix, start.add(outward.multiply(0.002F)),
                    end.add(outward.multiply(0.002F)), shortAxis,
                    halfWidth * 0.085F * taper, outward,
                    segment == 1 ? paleCore : coreColor, Math.round(242.0F * pulse));
        }
        for (int branch = 0; branch < 2; branch++) {
            int sample = branch + 1;
            Vec3d start = woundCorePoint(seed, index, sample, center, longAxis, shortAxis,
                    halfLength, halfWidth);
            float direction = branch == 0 ? -1.0F : 1.0F;
            Vec3d end = start.add(shortAxis.multiply(direction * halfWidth * 0.6F))
                    .add(longAxis.multiply((BoltPath.unit(seed + index * 181L, branch, 67L) - 0.5F)
                            * halfLength * 0.32F));
            woundGlowRibbon(vertices, matrix, start, end, longAxis,
                    Math.max(0.005F, halfWidth * 0.035F), outward,
                    branch == 0 ? purple : coreColor, Math.round(174.0F * pulse));
        }
    }

private static void drawGloamTendril(
            VertexConsumer vertices, Matrix4f matrix,
            Vec3d start, Vec3d end, float age, long seed,
            float reveal, int color, int alpha) {
        Vec3d span = end.subtract(start);
        if (span.lengthSquared() < 0.0001 || reveal <= 0.0F || alpha <= 0) {
            return;
        }
        Vec3d side = horizontalPerpendicular(span);
        double curlAmplitude = Math.min(0.18, 0.055 + span.length() * 0.025);
        Vec3d previous = start;
        float previousWidth = 0.085F;
        for (int segment = 1; segment <= 4; segment++) {
            float visible = MathHelper.clamp(reveal * 4.0F - segment + 1.0F, 0.0F, 1.0F);
            if (visible <= 0.0F) {
                break;
            }
            float progress = segment / 4.0F;
            float curl = (float) (MathHelper.sin(age * 0.065F + segment * 0.74F
                    + (float) BoltPath.unit(seed, segment, 347L) * 2.0F)
                    * curlAmplitude * MathHelper.sin(progress * MathHelper.PI));
            Vec3d fullNext = start.lerp(end, progress)
                    .add(side.multiply(curl))
                    .add(0.0, MathHelper.sin(progress * MathHelper.PI) * 0.055, 0.0);
            Vec3d next = previous.lerp(fullNext, visible);
            float nextWidth = MathHelper.lerp(progress, 0.085F, 0.025F);
            nextWidth = MathHelper.lerp(visible, previousWidth, nextWidth);
            Vec3d previousOffset = side.multiply(previousWidth);
            Vec3d nextOffset = side.multiply(nextWidth);
            woundColorQuad(vertices, matrix,
                    previous.add(previousOffset), previous.subtract(previousOffset),
                    next.subtract(nextOffset), next.add(nextOffset), color, alpha);
            woundColorQuad(vertices, matrix,
                    next.add(nextOffset), next.subtract(nextOffset),
                    previous.subtract(previousOffset), previous.add(previousOffset), color, alpha);
            Vec3d direction = next.subtract(previous);
            Vec3d cross = direction.lengthSquared() < 0.0001
                    ? UP
                    : direction.normalize().crossProduct(side).normalize();
            Vec3d previousCross = cross.multiply(previousWidth * 0.68F);
            Vec3d nextCross = cross.multiply(nextWidth * 0.68F);
            woundColorQuad(vertices, matrix,
                    previous.add(previousCross), previous.subtract(previousCross),
                    next.subtract(nextCross), next.add(nextCross), color, alpha);
            woundColorQuad(vertices, matrix,
                    next.add(nextCross), next.subtract(nextCross),
                    previous.subtract(previousCross), previous.add(previousCross), color, alpha);
            previous = next;
            previousWidth = nextWidth;
            if (visible < 1.0F) {
                break;
            }
        }
    }

