@Override
    public void render(SoulkeeperLanternVisualEntity entity, float yaw, float tickDelta, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        int count = MathHelper.clamp(entity.getLanternCount(), 0, MAX_LANTERN_COUNT);
        if (count <= 0) {
            return;
        }

        Vec3d center = getRenderCenter(entity, tickDelta);
        Vec3d entityPos = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ())
        );
        float speedMultiplier = Math.max(1.0F, entity.getSpeedMultiplier());
        double baseAngle = getSmoothRenderPhase(entity, tickDelta, speedMultiplier);
        double radius = Math.max(0.25F, entity.getOrbitRadius());

        for (int i = 0; i < count; i++) {
            double angle = baseAngle + ((Math.PI * 2.0) / count) * i;
            double bob = Math.sin(baseAngle * (BOB_SPEED / BASE_ANGULAR_SPEED) + i * 1.7) * BOB_AMPLITUDE;
            Vec3d lanternPos = center.add(Math.cos(angle) * radius, LANTERN_HEIGHT + bob, Math.sin(angle) * radius);
            Vec3d offset = lanternPos.subtract(entityPos);

            matrices.push();
            matrices.translate(offset.x, offset.y, offset.z);
            matrices.scale(LANTERN_RENDER_SCALE, LANTERN_RENDER_SCALE, LANTERN_RENDER_SCALE);
            matrices.translate(-0.5, 0.0, -0.5);
            MinecraftClient.getInstance().getBlockRenderManager().renderBlockAsEntity(
                    Blocks.SOUL_LANTERN.getDefaultState(),
                    matrices,
                    vertexConsumers,
                    light,
                    OverlayTexture.DEFAULT_UV
            );
            matrices.pop();
        }
    }

private static double getSmoothRenderPhase(SoulkeeperLanternVisualEntity entity, float tickDelta, float speedMultiplier) {
        float ageTicks = entity.age + tickDelta;
        RenderOrbitState state = RENDER_STATES.computeIfAbsent(entity.getId(), ignored -> new RenderOrbitState(entity.getOrbitPhase(), ageTicks));
        float deltaTicks = ageTicks - state.lastAgeTicks;
        if (deltaTicks < 0.0F || deltaTicks > 5.0F) {
            state.phase = entity.getOrbitPhase();
        } else if (deltaTicks > 0.0F) {
            state.phase += deltaTicks * BASE_ANGULAR_SPEED * speedMultiplier;
        }
        state.lastAgeTicks = ageTicks;
        while (state.phase > Math.PI * 2.0) {
            state.phase -= Math.PI * 2.0;
        }

        if (entity.age % 80 == 0) {
            Iterator<Map.Entry<Integer, RenderOrbitState>> iterator = RENDER_STATES.entrySet().iterator();
            while (iterator.hasNext()) {
                Map.Entry<Integer, RenderOrbitState> entry = iterator.next();
                if (entry.getKey() != entity.getId() && ageTicks - entry.getValue().lastAgeTicks > 100.0F) {
                    iterator.remove();
                }
            }
        }
        return state.phase;
    }

@Override
    public void render(T entity, float yaw, float tickDelta, MatrixStack matrices,
                       VertexConsumerProvider vertexConsumers, int light) {
        float age = entity.age + tickDelta;
        float seed = entity.getSpinSeed();

        matrices.push();

        Vec3d offset = resolveSmoothedOffset(entity, tickDelta);
        matrices.translate(offset.x, offset.y, offset.z);

        float flightYaw = MathHelper.lerpAngleDegrees(tickDelta, entity.prevYaw, entity.getFlightYaw());
        float flightPitch = MathHelper.lerp(tickDelta, entity.prevPitch, entity.getFlightPitch());
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-flightYaw));
        matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(flightPitch));

        matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees(seed + age * 6.0F));

        ParchmentRendering.renderBentPage(matrices, vertexConsumers, light,
                age, seed * 0.1F, 0.5F, 0.4F, 0.55F, 1.0F);
        matrices.pop();

        super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
    }

private static Vec3d getIdleAnchor(RevivalCandleVisualEntity candle, PlayerEntity owner, float tickDelta) {
        float ownerYaw = MathHelper.lerpAngleDegrees(tickDelta, owner.prevYaw, owner.getYaw());
        Vec3d ownerPos = new Vec3d(
                MathHelper.lerp(tickDelta, owner.prevX, owner.getX()),
                MathHelper.lerp(tickDelta, owner.prevY, owner.getY()),
                MathHelper.lerp(tickDelta, owner.prevZ, owner.getZ())
        );
        Vec3d forward = Vec3d.fromPolar(0.0F, ownerYaw).normalize();
        Vec3d right = new Vec3d(-forward.z, 0.0, forward.x);
        double side = candle.getWeaponType() == 2 ? -IDLE_SIDE_OFFSET : IDLE_SIDE_OFFSET;
        double bob = Math.sin((candle.age + tickDelta) * BOB_SPEED) * BOB_AMPLITUDE;
        return ownerPos
                .add(0.0, owner.getStandingEyeHeight() + IDLE_HEIGHT_OFFSET + bob, 0.0)
                .add(right.multiply(side))
                .add(forward.multiply(IDLE_BACK_OFFSET));
    }

private static Vec3d getActivationAnchor(PlayerEntity owner, float tickDelta) {
        Vec3d ownerPos = new Vec3d(
                MathHelper.lerp(tickDelta, owner.prevX, owner.getX()),
                MathHelper.lerp(tickDelta, owner.prevY, owner.getY()),
                MathHelper.lerp(tickDelta, owner.prevZ, owner.getZ())
        );
        Vec3d look = owner.getRotationVec(tickDelta).normalize();
        return ownerPos
                .add(0.0, owner.getStandingEyeHeight() + ACTIVE_HEIGHT_OFFSET, 0.0)
                .add(look.multiply(ACTIVE_FORWARD_OFFSET));
    }

@Override
    public void render(SoulstalkerStrideEntity entity, float yaw, float tickDelta,
                       MatrixStack matrices, VertexConsumerProvider consumers, int light) {
        if (IrisCompat.isRenderingShadowPass()) {
            return;
        }
        float time = entity.age + tickDelta;
        float appear = ease(MathHelper.clamp(time / 7.0F, 0.0F, 1.0F));
        if (appear <= 0.01F) {
            return;
        }
        Vec3d entityPosition = entity.getLerpedPos(tickDelta);
        LivingEntity owner = entity.getOwner();
        Vec3d ownerPosition = owner == null
                ? entityPosition.add(0.0, Config.uniqueEffects.soulstalker.riderHeight, 0.0)
                : owner.getLerpedPos(tickDelta);
        float rigYaw = owner == null ? entity.getYaw(tickDelta)
                : owner instanceof PlayerEntity
                ? MathHelper.lerpAngleDegrees(tickDelta, owner.prevYaw, owner.getYaw())
                : MathHelper.lerpAngleDegrees(tickDelta, owner.prevBodyYaw, owner.bodyYaw);
        Vec3d forward = horizontalFacing(rigYaw);
        Vec3d back = forward.multiply(-1.0);
        Vec3d right = rightFacing(rigYaw);
        byte surfaceMode = solveMode(entity.getSurfaceMode());
        RigState rig = RIGS.computeIfAbsent(entity, ignored -> new RigState());
        rig.beginFrame(entity, time);
        Vec3d[][] paths = new Vec3d[LEG_COUNT][];
        for (int leg = 0; leg < LEG_COUNT; leg++) {
            Vec3d root = rootPosition(ownerPosition, back, right, leg);
            SoulstalkerStrideContactSolver.Contact contact = surfaceMode == SoulstalkerStrideEntity.SURFACE_AIRBORNE
                    ? airborneContact(ownerPosition, back, right, leg)
                    : SoulstalkerStrideContactSolver.find(entity.getWorld(), entity, entityPosition, rigYaw,
                    MathHelper.clamp(Config.uniqueEffects.soulstalker.riderHeight, 0.5, 4.0),
                    surfaceMode, entity.getSurfaceNormal(), leg);
            Vec3d foot = rig.update(leg, contact.position(), contact.normal(), time, surfaceMode);
            paths[leg] = buildPath(root, foot, contact.normal(), back, right,
                    entityPosition, leg, time, surfaceMode);
        }
        boolean firstPersonOwner = isFirstPersonOwner(entity);
        int packedLight = LightmapTextureManager.pack(
                Math.max(2, LightmapTextureManager.getBlockLightCoordinates(light)),
                LightmapTextureManager.getSkyLightCoordinates(light));
        Matrix4f matrix = matrices.peek().getPositionMatrix();
        VertexConsumer dark = consumers.getBuffer(RenderLayer.getDebugQuads());
        for (int leg = 0; leg < LEG_COUNT; leg++) {
            Vec3d[] path = paths[leg];
            int start = firstPersonOwner ? 2 : 0;
            for (int segment = start; segment < path.length - 1; segment++) {
                float progress = segment / (float) (path.length - 1);
                float width = MathHelper.lerp(progress, 0.17F, 0.058F) * appear;
                int color = ((segment + leg) & 1) == 0 ? DARK_CORE : DARK_PURPLE;
                SoulstalkerRenderGeometry.prism(dark, matrix, path[segment], path[segment + 1],
                        width, color, Math.round(246.0F * appear), packedLight, false);
            }
        }
        super.render(entity, yaw, tickDelta, matrices, consumers, light);
    }

public void render(PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn, EntityKangaroo roo, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
        matrixStackIn.pushPose();
        if(roo.isRoger()){
            ItemStack haloStack = new ItemStack(AMItemRegistry.HALO.get());
            matrixStackIn.pushPose();
            translateToHead(matrixStackIn);
            float f = 0.1F * (float) Math.sin((roo.tickCount + partialTicks) * 0.1F) + (roo.isBaby() ? 0.2F : 0F);
            matrixStackIn.translate(0.0F, -0.75F - f, -0.2F);
            matrixStackIn.mulPose(Axis.XP.rotationDegrees(90F));
            matrixStackIn.scale(1.3F, 1.3F, 1.3F);
            ItemInHandRenderer renderer = Minecraft.getInstance().getEntityRenderDispatcher().getItemInHandRenderer();
            renderer.renderItem(roo, haloStack, ItemDisplayContext.GROUND, false, matrixStackIn, bufferIn, packedLightIn);
            matrixStackIn.popPose();
        }
        if(!roo.isBaby()) {
            {
                matrixStackIn.pushPose();
                ItemStack itemstack = roo.getItemBySlot(EquipmentSlot.HEAD);
                if (itemstack.getItem() instanceof ArmorItem) {
                    ArmorItem armoritem = (ArmorItem) itemstack.getItem();
                    if (itemstack.canEquip(EquipmentSlot.HEAD, roo)) {
                        HumanoidModel a = defaultBipedModel;
                        a = getArmorModelHook(roo, itemstack, EquipmentSlot.HEAD, a);
                        final boolean notAVanillaModel = a != defaultBipedModel;
                        this.setModelSlotVisible(a, EquipmentSlot.HEAD);
                        translateToHead(matrixStackIn);
                        matrixStackIn.translate(0, 0.015F, -0.05F);
                        if(itemstack.getItem() == AMItemRegistry.FEDORA.get()){
                            matrixStackIn.translate(0, 0.05F, 0F);

                        }
                        matrixStackIn.scale(0.7F, 0.7F, 0.7F);
                        final boolean flag1 = itemstack.hasFoil();
                        int clampedLight = packedLightIn;
                        if (armoritem instanceof net.minecraft.world.item.DyeableLeatherItem) { // Allow this for anything, not only cloth
                            final int i = ((net.minecraft.world.item.DyeableLeatherItem) armoritem).getColor(itemstack);
                            final float f = (float) (i >> 16 & 255) / 255.0F;
                            final float f1 = (float) (i >> 8 & 255) / 255.0F;
                            final float f2 = (float) (i & 255) / 255.0F;
                            renderHelmet(roo, matrixStackIn, bufferIn, clampedLight, flag1, a, f, f1, f2, getArmorResource(roo, itemstack, EquipmentSlot.HEAD, null), notAVanillaModel);
                            renderHelmet(roo, matrixStackIn, bufferIn, clampedLight, flag1, a, 1.0F, 1.0F, 1.0F, getArmorResource(roo, itemstack, EquipmentSlot.HEAD, "overlay"), notAVanillaModel);
                        } else {
                            renderHelmet(roo, matrixStackIn, bufferIn, clampedLight, flag1, a, 1.0F, 1.0F, 1.0F, getArmorResource(roo, itemstack, EquipmentSlot.HEAD, null), notAVanillaModel);
                        }
                    }
                }else{
                    translateToHead(matrixStackIn);
                    matrixStackIn.translate(0, -0.2, -0.1F);
                    matrixStackIn.mulPose((new Quaternionf()).rotateX(Mth.PI));
                    matrixStackIn.mulPose((new Quaternionf()).rotateY(Mth.PI));
                    matrixStackIn.scale(1.0F, 1.0F, 1.0F);
                    Minecraft.getInstance().getItemRenderer().renderStatic(itemstack, ItemDisplayContext.FIXED, packedLightIn, OverlayTexture.NO_OVERLAY, matrixStackIn, bufferIn, roo.level(), 0);
                }
                matrixStackIn.popPose();
            }
            {
                matrixStackIn.pushPose();
                ItemStack itemstack = roo.getItemBySlot(EquipmentSlot.CHEST);
                if (itemstack.getItem() instanceof ArmorItem) {
